/* OZA DC Hub — isolated CMA project interface. */
(function(){'use strict';
const KEY='cma_dhc1295_v1',META='cma_dhc1295_meta_v1',THEME='cma_dhc1295_theme',HASH='609e64c69f6ecd42f6820a05e3e259799a2015ad7b83cd62268f54e1233a95e9';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>crypto.randomUUID(),today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
let data=null,meta={},view='dashboard',unlocked=false,failures=0,cooldown=0,remoteFingerprint='',newSnapshot=false,polling=false,draft=null,importCandidate=null;
let filters={discipline:'',type:'',form:'',owner:'',status:'',search:'',group:''};
const owners=['Eng. Muhammad Sheta','Technical Office','HSE','QA/QC','Administrative & Finance'];
const status=k=>CMA.STATUS[k]||CMA.STATUS.UNRECORDED,docs=t=>t.documentIds.map(id=>data.documents.find(d=>d.id===id)).filter(Boolean),isResponse=s=>/^CODE_[ABCD]$/.test(s),reserved=()=>data.documents.filter(d=>!data.transmittals.some(t=>t.documentIds.includes(d.id)));
const badge=k=>`<span class="badge" style="--c:${esc(status(k).color)}">${esc(status(k).label)}</span>`;
const button=(label,action,cls='secondary',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function error(e){toast(e.message||String(e));console.error(e);}
function modal(html){$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal();$('modal').scrollTop=0;}
function field(label,id,type='text',value='',extra=''){return `<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,id,items,value='',blank='Select…'){return `<label class="field">${label}<select id="${id}">${blank!==null?`<option value="">${blank}</option>`:''}${Object.entries(items).map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(k===v?v:k+' · '+v)}</option>`).join('')}</select></label>`;}
function ownerField(id,value=''){let list=[...new Set([...owners,...data.transmittals.map(t=>t.owner).filter(Boolean),value].filter(Boolean))];return `<label class="field">Owner<select id="${id}"><option value="">Not recorded</option>${list.map(n=>`<option ${n===value?'selected':''}>${esc(n)}</option>`).join('')}<option value="__add">+ Add owner…</option></select></label>`;}
function readOwner(id){let val=$(id).value;if(val==='__add'){let n=prompt('Owner name');if(!n||!n.trim())throw Error('Enter an owner or choose Not recorded.');val=n.trim();}return val;}
function requireEditor(){if(!unlocked)throw Error('Unlock editing to make changes.');}
function commit(candidate){requireEditor();CMA.validate(candidate);const saved=clone(candidate);saved.version='local-'+Date.now();localStorage.setItem(KEY,JSON.stringify(saved));meta={...meta,dirty:true,savedAt:new Date().toISOString()};localStorage.setItem(META,JSON.stringify(meta));data=saved;render();}
function mutate(fn){let next=clone(data);fn(next);commit(next);}
function snapshot(t,kind='snapshot',reason=''){return {id:uid(),at:today(),status:t.status,rev:t.rev,owner:t.owner,kind,reason,title:t.title,submittedDate:t.submittedDate,responseDate:t.responseDate,documentIds:[...t.documentIds]};}
async function fingerprint(x){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(x))))].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function fetchSnapshot(){let r=await fetch('./cma-data.json?_='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('Published snapshot is unavailable ('+r.status+').');let x=await r.json();CMA.validate(x);return {snapshot:x,fp:await fingerprint(x)};}
function stateText(){if(!data)return;let text=`${data.transmittals.length} transmittals · ${data.documents.length} documents · ${meta.dirty?'Local changes saved on this device':'Published snapshot'}`;if(newSnapshot)text+=' · Updated snapshot available';$('snapshot-state').textContent=text;$('update-dot').hidden=!newSnapshot;$('new-tn').disabled=newSnapshot;$('new-tn').title=newSnapshot?'Refresh the updated snapshot before allocating new numbers':'';}
async function poll(){if(polling)return;polling=true;try{let r=await fetchSnapshot();remoteFingerprint=r.fp;if(meta.baseFingerprint&&r.fp!==meta.baseFingerprint){newSnapshot=true;stateText();}}catch(e){console.warn(e.message);}finally{polling=false;}}
async function refresh(){try{const r=await fetchSnapshot();if(meta.dirty&&!confirm('This device has local changes. Refresh replaces them with the published snapshot. Download a JSON backup first if you need to keep them. Continue?'))return;if(draft&&!confirm('Discard the open transmittal draft and refresh?'))return;localStorage.setItem(KEY,JSON.stringify(r.snapshot));meta={baseFingerprint:r.fp,dirty:false,refreshedAt:new Date().toISOString()};localStorage.setItem(META,JSON.stringify(meta));data=r.snapshot;newSnapshot=false;draft=null;remoteFingerprint=r.fp;$('modal').close();render();toast('Published snapshot refreshed.');}catch(e){error(e);}}
function age(t){if(!t.submittedDate)return null;return CMA.workingDays(t.submittedDate,isResponse(t.status)?t.responseDate:today());}
function withParty(t){return t.status==='UNRECORDED'?'Not recorded':isResponse(t.status)?'DC':status(t.status).stage==='Authors'?(t.owner||'Authors'):status(t.status).stage;}
function matches(t){let ds=docs(t),q=filters.search.toLowerCase();return (!filters.discipline||(t.discipline===filters.discipline||ds.some(d=>d.discipline===filters.discipline)))&&(!filters.type||ds.some(d=>d.type===filters.type))&&(!filters.form||t.form===filters.form)&&(!filters.owner||(t.owner||'__none')===filters.owner)&&(!filters.status||t.status===filters.status)&&(!q||[t.num,t.title,...ds.flatMap(d=>[d.num,d.title])].join(' ').toLowerCase().includes(q))&&(!filters.group||groupTest(t,filters.group));}
function groupTest(t,g){if(g==='internal')return ['PREPARING','INTERNAL','INTERNAL_REVISE','READY'].includes(t.status);if(g==='revision')return ['CODE_B','CODE_C','INTERNAL_REVISE'].includes(t.status);if(g==='approved')return ['CODE_A','CODE_D'].includes(t.status);if(g.startsWith('age:')){let a=age(t),band=g.slice(4);return t.status==='SUBMITTED'&&a!==null&&(band==='0–5'?a<=5:band==='6–10'?a>=6&&a<=10:band==='11–20'?a>=11&&a<=20:a>20);}return true;}
function filtered(){return data.transmittals.filter(matches);}
function openFilter(f){filters={discipline:'',type:'',form:'',owner:'',status:'',search:'',group:'',...f};view='register';render();}
function nav(v){view=v;render();}
function kpis(){let ts=data.transmittals;return [{name:'Total transmittals',n:ts.length,f:{},c:'#7185a0'},{name:'With consultant',n:ts.filter(t=>t.status==='SUBMITTED').length,f:{status:'SUBMITTED'},c:'#2563eb'},{name:'Internal action',n:ts.filter(t=>groupTest(t,'internal')).length,f:{group:'internal'},c:'#7c3aed'},{name:'Needs revision',n:ts.filter(t=>groupTest(t,'revision')).length,f:{group:'revision'},c:'#d97706'},{name:'Approved or closed',n:ts.filter(t=>groupTest(t,'approved')).length,f:{group:'approved'},c:'#218260'},{name:'Not recorded',n:ts.filter(t=>t.status==='UNRECORDED').length,f:{status:'UNRECORDED'},c:'#64748b'}];}
function metricHTML(){return `<div class="metrics">${kpis().map((k,i)=>`<button class="metric" style="--c:${k.c}" data-kpi="${i}"><strong>${k.n}</strong><span>${k.name}</span></button>`).join('')}</div>`;}
function counts(key){let out={};data.transmittals.forEach(t=>{let vals=key==='discipline'?[...new Set([t.discipline,...docs(t).map(d=>d.discipline)].filter(Boolean))]:[key==='owner'?(t.owner||'Not recorded'):t[key]];vals.forEach(v=>out[v]=(out[v]||0)+1);});return out;}
function bars(items,filterKey,units='TN'){let max=Math.max(1,...Object.values(items));return Object.entries(items).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`<button class="bar-row" ${filterKey?`data-filter-key="${filterKey}" data-filter-value="${esc(k)}"`:''}><span>${esc(k)}${units==='days'?' <small>days</small>':''}</span><span class="bar-track"><i style="width:${n/max*100}%"></i></span><b>${Number.isInteger(n)?n:n.toFixed(1)}</b></button>`).join('')||'<div class="empty">No recorded data</div>';}
function table(ts){return `<div class="table-wrap"><table><thead><tr>${['No','Transmittal number','Description','Owner','Rev','Status','With','Age'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${ts.map((t,i)=>`<tr><td data-label="No">${i+1}</td><td data-label="Transmittal number"><button class="link number" data-tn="${esc(t.id)}">${esc(t.num)}</button></td><td class="description" data-label="Description">${esc(t.title||'Untitled transmittal')}<small>${t.documentIds.length} documents${t.titleSource?' · Grouping label':''}</small></td><td data-label="Owner">${esc(t.owner||'Not recorded')}</td><td data-label="Revision">${esc(t.rev)}</td><td data-label="Status">${badge(t.status)}</td><td data-label="With">${esc(withParty(t))}</td><td class="nowrap" data-label="Age">${age(t)===null?'—':age(t)+'d'}</td></tr>`).join('')}</tbody></table>${!ts.length?'<div class="empty">No transmittals match these filters.</div>':''}</div>`;}
function parties(){return `<div class="parties"><div class="intro"><b>CMA Security System Stage 3</b><small>DHC 1295</small></div>${[['Client','CCIS','data:image/png;base64,'],['Consultant','Designshouse','data:image/png;base64,'],['Contractor','OZA','data:image/png;base64,']].map(([l,n,s])=>`<div class="party">${l}<img src="${s}" alt="${n}"></div>`).join('')}</div>`;}
function dashboard(){return parties()+metricHTML()+`<div class="stats-line"><span><b>${data.documents.length}</b> unique documents</span><span><b>${data.documents.length-reserved().length}</b> linked documents</span><button class="link" data-action="reserved"><b>${reserved().length}</b> reserved documents</button><span><b>${data.transmittals.reduce((s,t)=>s+t.documentIds.length,0)}</b> TN–document links</span></div><div class="grid"><section class="panel"><h2>Transmittals by form</h2><p class="subline">Each transmittal counted once</p>${bars(counts('form'),'form')}</section><section class="panel"><h2>Current workflow</h2><p class="subline">Select a status to inspect its transmittals</p>${bars(Object.fromEntries(Object.keys(CMA.STATUS).map(k=>[k,data.transmittals.filter(t=>t.status===k).length]).filter(x=>x[1])),'status').replace(/<span>([A-Z_]+)<\/span>/g,(m,k)=>'<span>'+esc(status(k).label)+'</span>')}</section></div><div class="section-title"><h2>Transmittal overview</h2>${button('View register','register')}</div>${table(data.transmittals.slice(0,5))}`;}
function timing(){let groups={};data.transmittals.forEach(t=>{let entries=[...t.history.filter(e=>e.submittedDate&&e.responseDate),...(t.submittedDate&&t.responseDate?[t]:[])];let seen=new Set();entries.forEach(e=>{let key=[e.rev,e.submittedDate,e.responseDate].join('|');if(seen.has(key))return;seen.add(key);let a=CMA.workingDays(e.submittedDate,e.responseDate);if(a!==null)(groups[t.form]??=[]).push(a);});});return Object.fromEntries(Object.entries(groups).map(([k,a])=>[k,a.reduce((x,y)=>x+y,0)/a.length]));}
function insights(){let bands=Object.fromEntries(['0–5','6–10','11–20','21+'].map(b=>[b,data.transmittals.filter(t=>groupTest(t,'age:'+b)).length]));return `<div class="notice">Transmittal counts reflect the current revision. A transmittal containing several disciplines appears in each relevant discipline. Response timing uses recorded submission and response dates only.</div><div class="grid"><section class="panel"><h2>By transmittal form</h2>${bars(counts('form'),'form')}</section><section class="panel"><h2>By contained discipline</h2>${bars(counts('discipline'),'discipline')}</section><section class="panel"><h2>By owner</h2>${bars(counts('owner'),'owner')}</section><section class="panel"><h2>Consultant waiting age</h2><p class="subline">Working days · only submissions with dates</p>${bars(bands,'age')}</section><section class="panel"><h2>Recorded response time by form</h2><p class="subline">Mean working days per recorded revision</p>${bars(timing(),null,'days')}</section><section class="panel"><h2>Record completeness</h2>${bars({'Owner recorded':data.transmittals.filter(t=>t.owner).length,'Submission recorded':data.transmittals.filter(t=>t.submittedDate).length,'Response recorded':data.transmittals.filter(t=>t.responseDate).length,'History recorded':data.transmittals.filter(t=>t.history.length).length},null)}<p class="subline">Missing records remain blank; no past workflow is inferred.</p></section></div>`;}
function register(){return `<div class="filters">${select('Discipline','f-discipline',{...data.catalogs.disciplines,...Object.fromEntries(data.transmittals.filter(t=>t.discipline&&!data.catalogs.disciplines[t.discipline]).map(t=>[t.discipline,t.discipline==='OTH'?'Other':t.discipline]))},filters.discipline,'All disciplines')}${select('Document type','f-type',data.catalogs.documentTypes,filters.type,'All document types')}${select('Transmittal form','f-form',CMA.FORMS,filters.form,'All forms')}${select('Owner','f-owner',Object.fromEntries([['__none','Not recorded'],...[...new Set(data.transmittals.map(t=>t.owner).filter(Boolean))].map(o=>[o,o])]),filters.owner,'All owners')}${select('Status','f-status',Object.fromEntries(Object.entries(CMA.STATUS).map(([k,v])=>[k,v.label])),filters.status,'All statuses')}<div class="search-row"><input id="f-search" type="search" placeholder="Search TN or document number / title" value="${esc(filters.search)}" aria-label="Search transmittals and contained documents">${button('Reset filters','reset')}${filters.group?`<span class="badge" style="--c:#64748b">${esc(filters.group)}</span>`:''}</div></div><div class="section-title"><div><b>${filtered().length}</b> of ${data.transmittals.length} transmittals <small>· contained documents in details</small></div>${button('Export filtered CSV','csv')}</div>${table(filtered())}`;}
function render(){if(!data)return;$('view-title').textContent={dashboard:'Project dashboard',insights:'Project insights',register:'Transmittal register'}[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('content').innerHTML=view==='dashboard'?dashboard():view==='insights'?insights():register();$('lock').querySelector('span').textContent=unlocked?'Editing unlocked':'View only';$('new-tn').hidden=!unlocked;stateText();}
function historyHTML(t){if(!t.history.length)return '<p class="notice">No workflow history recorded for this imported transmittal.</p>';return `<div class="timeline">${[...t.history].reverse().map(e=>`<div class="event"><b>${esc(e.at)} · Revision ${esc(e.rev)} · ${esc(status(e.status).label)}</b><small>${esc(e.kind)}${e.owner?' · '+esc(e.owner):''}${e.reason?' · '+esc(e.reason):''}</small>${e.submittedDate||e.responseDate?`<small>Submission ${esc(e.submittedDate||'—')} · Response ${esc(e.responseDate||'—')}</small>`:''}</div>`).join('')}</div>`;}
function detail(id){let t=data.transmittals.find(t=>t.id===id);if(!t)return;modal(`<h2 class="modal-title number">${esc(t.num)}</h2><p>${esc(t.title||'Untitled transmittal')}${t.titleSource?' <small>· Grouping label</small>':''}</p>${badge(t.status)}<div class="detail-meta"><div><small>Revision</small>${esc(t.rev)}</div><div><small>Owner</small>${esc(t.owner||'Not recorded')}</div><div><small>With</small>${esc(withParty(t))}</div><div><small>Working-day age</small>${age(t)===null?'—':age(t)+' days'}</div><div><small>Submission</small>${esc(t.submittedDate||'—')}</div><div><small>Response</small>${esc(t.responseDate||'—')}</div><div><small>Consultant timing</small>${t.submittedDate&&t.responseDate?CMA.workingDays(t.submittedDate,t.responseDate)+' days':'—'}</div><div><small>Internal review timing</small>${internalDays(t)}</div></div><div class="section-title"><h3>Contained documents (${t.documentIds.length})</h3></div><div class="doc-list">${docs(t).map(d=>`<div class="doc-item"><div><button class="link number" data-doc="${esc(d.id)}">${esc(d.num)}</button><p>${esc(d.title||'Reserved / title not recorded')}</p><small>Revision ${esc(t.rev)} · ${esc(status(t.status).label)}</small></div></div>`).join('')}</div><div class="section-title"><h3>Recorded history</h3></div>${historyHTML(t)}${unlocked?`<div class="actions">${button('Correct details','correct-tn','secondary',`data-id="${esc(t.id)}"`)}${isResponse(t.status)?button((['CODE_A','CODE_D'].includes(t.status)?'Reopen':'Start revision')+' → '+CMA.nextRevision(t),'revision','',`data-id="${esc(t.id)}"`):button('Update workflow','workflow','',`data-id="${esc(t.id)}"`)}</div>`:''}`);}
function internalDays(t){let entries=t.history.filter(e=>e.rev===t.rev),a=entries.find(e=>e.status==='INTERNAL'),b=a&&entries.find(e=>e.at>=a.at&&['READY','SUBMITTED'].includes(e.status));return a&&b?CMA.workingDays(a.at,b.at)+' days':'—';}
function documentDetail(id){let d=data.documents.find(d=>d.id===id);if(!d)return;let links=data.transmittals.filter(t=>t.documentIds.includes(id));modal(`<h2 class="modal-title number">${esc(d.num)}</h2><p>${esc(d.title||'Reserved / title not recorded')}</p><div class="stats-line"><span>${esc(d.type)} · ${esc(data.catalogs.documentTypes[d.type]||'')}</span><span>${esc(d.discipline)} · ${esc(data.catalogs.disciplines[d.discipline]||'')}</span></div><h3 style="margin-top:22px">Linked transmittals (${links.length})</h3><p class="subline">Revision and status belong to each transmittal, not to the shared document identity.</p><div class="doc-list">${links.map(t=>`<div class="doc-item"><div><button class="link number" data-tn="${esc(t.id)}">${esc(t.num)}</button><p>Revision ${esc(t.rev)} · ${esc(t.owner||'Owner not recorded')}</p>${badge(t.status)}</div></div>`).join('')||'<div class="notice">Reserved number — not linked to a transmittal.</div>'}</div>${d.corrections?.length?'<h3 style="margin-top:20px">Title correction audit</h3>'+d.corrections.map(c=>'<div class="notice">'+esc(c.at)+' · '+esc(c.reason)+'<br><small>Previous: '+esc(c.previousTitle||'Not recorded')+'</small></div>').join(''):''}${unlocked?`<div class="actions">${button('Correct document title','correct-doc','secondary',`data-id="${esc(id)}"`)}</div>`:''}`);}
function workflow(id){requireEditor();let t=data.transmittals.find(t=>t.id===id);modal(`<h2>Update workflow</h2><p class="number">${esc(t.num)} · Revision ${esc(t.rev)}</p><form id="workflow-form"><div class="form-grid">${select('Status','w-status',Object.fromEntries(Object.entries(CMA.STATUS).filter(([k])=>k!=='UNRECORDED').map(([k,v])=>[k,v.label])),t.status,'Choose recorded status')}${field('Effective date','w-date','date',today(),'required')}${field('Submission date (where recorded)','w-submitted','date',t.submittedDate)}${field('Response date (where recorded)','w-response','date',t.responseDate)}</div><div class="notice">A consultant response requires a recorded submission date. All contained documents follow this transmittal’s revision and status.</div><div class="actions"><button class="button" type="submit">Save workflow</button></div></form>`);$('workflow-form').onsubmit=e=>{e.preventDefault();try{let s=$('w-status').value,at=$('w-date').value,sub=$('w-submitted').value,res=$('w-response').value;if(!s)throw Error('Choose a status.');if(s==='SUBMITTED'&&sub&&sub!==at)throw Error('Use the submission date as the effective date.');if(isResponse(s)&&res&&res!==at)throw Error('Use the response date as the effective date.');mutate(n=>{let x=n.transmittals.find(t=>t.id===id);x.history.push({...snapshot(x),at});x.submittedDate=sub;x.responseDate=res;CMA.setStatus(n,id,s,at);});detail(id);toast('Workflow updated.');}catch(x){error(x);}};}
function correctTN(id){requireEditor();let t=data.transmittals.find(t=>t.id===id);modal(`<h2>Correct transmittal details</h2><p class="number">${esc(t.num)} · Revision ${esc(t.rev)}</p><form id="correct-form"><div class="form-grid">${field('Title','c-title','text',t.title)}${ownerField('c-owner',t.owner)}${field('Correction reason','c-reason','text','','required')}</div><p class="subline">Identity and revision are unchanged. The previous details are retained in history.</p><div class="actions"><button class="button">Save correction</button></div></form>`);$('correct-form').onsubmit=e=>{e.preventDefault();try{let title=$('c-title').value.trim(),owner=readOwner('c-owner'),reason=$('c-reason').value.trim();if(!reason)throw Error('A correction reason is required.');mutate(n=>{let x=n.transmittals.find(t=>t.id===id);x.history.push(snapshot(x,'correction',reason));x.title=title;x.owner=owner;delete x.titleSource;});detail(id);toast('Correction saved with audit reason.');}catch(x){error(x);}};}
function correctDoc(id){requireEditor();let d=data.documents.find(d=>d.id===id);modal(`<h2>Correct document title</h2><p class="number">${esc(d.num)}</p><form id="correct-doc-form">${field('Title','d-title','text',d.title)}${field('Correction reason','d-reason','text','','required')}<div class="actions"><button class="button">Save correction</button></div></form>`);$('correct-doc-form').onsubmit=e=>{e.preventDefault();try{let title=$('d-title').value.trim(),reason=$('d-reason').value.trim();if(!reason)throw Error('A correction reason is required.');mutate(n=>{let x=n.documents.find(d=>d.id===id);(x.corrections??=[]).push({id:uid(),at:today(),previousTitle:x.title,title,reason});x.title=title;});documentDetail(id);}catch(x){error(x);}};}
async function unlock(){if(unlocked){unlocked=false;render();toast('Editing locked.');return;}modal(`<h2>Unlock editing</h2><p>Enter the editing PIN for this tab.</p><form id="unlock-form">${field('Editing PIN','pin','password','','required autocomplete="off" inputmode="numeric"')}<div id="unlock-error" class="notice" hidden></div><div class="actions"><button class="button">Unlock</button></div></form>`);$('unlock-form').onsubmit=async e=>{e.preventDefault();try{if(Date.now()<cooldown)throw Error('Too many attempts. Try again in '+Math.ceil((cooldown-Date.now())/1000)+' seconds.');let pin=$('pin').value;$('pin').value='';let h=await fingerprintText(pin);if(h!==HASH){failures++;if(failures>=5){cooldown=Date.now()+60000;failures=0;}throw Error(cooldown>Date.now()?'Too many attempts. Please wait 60 seconds.':'Incorrect PIN.');}unlocked=true;failures=0;$('modal').close();render();toast('Editing unlocked for this tab.');}catch(x){$('unlock-error').hidden=false;$('unlock-error').textContent=x.message;}};setTimeout(()=>$('pin')?.focus(),30);}
async function fingerprintText(x){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(x)))].map(b=>b.toString(16).padStart(2,'0')).join('');}

function newTN(){requireEditor();if(newSnapshot)throw Error('Refresh the updated snapshot before creating a transmittal.');if(!draft)draft={form:'DTF',serial:CMA.nextTnSerial(data,'DTF'),title:'',owner:'',documents:[]};composer();}
function saveDraftFields(){if(!$('n-form'))return;draft.form=$('n-form').value;draft.serial=Number($('n-serial').value);draft.title=$('n-title').value;draft.owner=$('n-owner').value;}
function composer(){modal('<h2>New transmittal</h2><p>Choose a form and compose its document list.</p><div class="form-grid">'+select('Transmittal form','n-form',CMA.FORMS,draft.form,null)+field('Serial (automatic or manual)','n-serial','number',draft.serial,'min="1" step="1" required')+'<div class="full notice number" id="tn-preview"></div>'+field('Transmittal title','n-title','text',draft.title)+ownerField('n-owner',draft.owner)+'</div><div id="tn-conflicts"></div><div class="section-title"><h3>Contained documents ('+draft.documents.length+')</h3></div><div class="doc-list">'+draft.documents.map((d,i)=>'<div class="doc-item"><div><span class="number">'+esc(d.num)+'</span><p>'+esc(d.title||'Reserved / title not recorded')+'</p><small>'+(data.documents.some(x=>x.id===d.id)?'Existing document':'New document')+'</small></div>'+button('Remove','remove-draft','secondary','data-index="'+i+'"')+'</div>').join('')+'</div><div class="actions">'+button('Use existing / reserved','pick-existing')+button('+ New document','compose-doc')+'</div><div class="actions">'+button('Discard draft','discard-draft')+button('Create & copy TN','create-tn','')+'</div>');$('n-form').onchange=()=>{saveDraftFields();draft.serial=CMA.nextTnSerial(data,draft.form);$('n-serial').value=draft.serial;previewTN();};$('n-serial').oninput=previewTN;previewTN();}
function conflictHTML(c){return c.transmittals.map(t=>'<div class="notice error">Number already exists: <button class="link number" data-tn="'+esc(t.id)+'">'+esc(t.num)+'</button> · '+esc(status(t.status).label)+'</div>').join('')+c.documents.map(d=>'<div class="notice error">Document already exists: <button class="link number" data-doc="'+esc(d.id)+'">'+esc(d.num)+'</button>'+d.relatedTransmittals.map(t=>'<div><button class="link number" data-tn="'+esc(t.id)+'">'+esc(t.num)+'</button> · '+esc(status(t.status).label)+'</div>').join('')+'</div>').join('');}
function previewTN(){try{let num=CMA.tnNumber($('n-form').value,Number($('n-serial').value));$('tn-preview').textContent=num;$('tn-conflicts').innerHTML=conflictHTML(CMA.findConflicts(data,{tnNum:num}));}catch(e){$('tn-preview').textContent=e.message;}}
function pickExisting(){saveDraftFields();modal('<h2>Use existing documents</h2><p>Select existing identities instead of creating duplicates. Reserved numbers are included.</p><input id="pick-search" type="search" placeholder="Search full number or title" aria-label="Search existing documents"><label class="field"><span><input type="checkbox" id="pick-reserved"> Reserved numbers only</span></label><div id="pick-list" class="picker"></div><div class="actions">'+button('Back to draft','resume-draft')+'</div>');const draw=()=>{let q=$('pick-search').value.toLowerCase(),only=$('pick-reserved').checked,rs=new Set(reserved().map(d=>d.id));$('pick-list').innerHTML=data.documents.filter(d=>(!only||rs.has(d.id))&&[d.num,d.title].join(' ').toLowerCase().includes(q)).map(d=>'<button data-pick="'+esc(d.id)+'" '+(draft.documents.some(x=>x.id===d.id)?'disabled':'')+'><span class="number">'+esc(d.num)+'</span>'+esc(d.title||'Reserved / title not recorded')+' <small>· '+(rs.has(d.id)?'Reserved':data.transmittals.filter(t=>t.documentIds.includes(d.id)).length+' linked TN')+'</small></button>').join('');};$('pick-search').oninput=draw;$('pick-reserved').onchange=draw;draw();}
function composeDoc(){saveDraftFields();let type=Object.keys(data.catalogs.documentTypes)[0],disc=Object.keys(data.catalogs.disciplines)[0];modal('<h2>Add new document</h2><div class="actions" style="justify-content:flex-start;margin:10px 0 16px">'+button('+ Add document type','catalog-type')+button('+ Add discipline','catalog-discipline')+'</div><div class="form-grid">'+select('Document type','nd-type',data.catalogs.documentTypes,type,null)+select('Discipline','nd-disc',data.catalogs.disciplines,disc,null)+field('Serial (automatic or manual)','nd-serial','number',1,'min="1" step="1"')+field('Document title','nd-title')+'<div class="full notice number" id="nd-preview"></div></div><div id="nd-conflicts"></div><div class="actions">'+button('Back to draft','resume-draft')+button('Add to draft','add-doc','')+'</div>');const auto=()=>{$('nd-serial').value=Math.max(CMA.nextDocSerial(data,$('nd-type').value,$('nd-disc').value),...draft.documents.filter(d=>d.type===$('nd-type').value&&d.discipline===$('nd-disc').value).map(d=>d.serial+1));previewDoc();};$('nd-type').onchange=auto;$('nd-disc').onchange=auto;$('nd-serial').oninput=previewDoc;auto();}
function previewDoc(){try{let num=CMA.docNumber($('nd-type').value,$('nd-disc').value,Number($('nd-serial').value));$('nd-preview').textContent=num;$('nd-conflicts').innerHTML=conflictHTML(CMA.findConflicts(data,{docNum:num}))+(draft.documents.some(d=>d.num===num)?'<div class="notice error">This number is already in the draft.</div>':'');}catch(e){$('nd-preview').textContent=e.message;}}
function addDoc(){requireEditor();let type=$('nd-type').value,discipline=$('nd-disc').value,serial=Number($('nd-serial').value),num=CMA.docNumber(type,discipline,serial);if(CMA.findConflicts(data,{docNum:num}).documents.length||draft.documents.some(d=>d.num===num))throw Error('Document number already exists. Use the existing document picker.');draft.documents.push({id:uid(),num,type,discipline,serial,title:$('nd-title').value.trim()});composer();}
async function createTN(){requireEditor();saveDraftFields();await poll();if(newSnapshot)throw Error('An updated published snapshot is available. Back up local changes and refresh before creating numbers.');let num=CMA.tnNumber(draft.form,draft.serial);if(CMA.findConflicts(data,{tnNum:num}).transmittals.length){composer();throw Error('Transmittal number already exists.');}let owner=readOwner('n-owner');let createdId=uid();mutate(n=>{draft.documents.forEach(d=>{if(!n.documents.some(x=>x.id===d.id)){if(n.documents.some(x=>x.num===d.num))throw Error('Document number conflict: '+d.num);n.documents.push(clone(d));}});n.transmittals.push({id:createdId,num,form:draft.form,serial:draft.serial,title:draft.title.trim(),rev:'0',status:'PREPARING',owner,submittedDate:'',responseDate:'',documentIds:draft.documents.map(d=>d.id),history:[{id:uid(),at:today(),status:'PREPARING',rev:'0',owner,kind:'status'}]});});draft=null;try{await navigator.clipboard.writeText(num);toast('Transmittal created. Number copied to clipboard.');}catch(e){toast('Transmittal created. Copy number: '+num);}detail(createdId);}
function reservedDialog(){modal('<h2>Reserved document numbers</h2><p>These identities are retained without a linked transmittal. They can be selected when composing a new transmittal.</p><div class="doc-list">'+reserved().map(d=>'<div class="doc-item"><div><button class="link number" data-doc="'+esc(d.id)+'">'+esc(d.num)+'</button><p>'+esc(d.title||'Title not recorded')+'</p></div></div>').join('')+'</div>');}

function download(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function flatRows(ts=data.transmittals,includeReserved=true){let rows=[];ts.forEach(t=>{let ds=docs(t);(ds.length?ds:[null]).forEach(d=>rows.push({'Form':t.form,'Document Name':d?.title||'','Document Number':d?.num||'','Transmittal Number':t.num,'Transmittal Title':t.title,'Owner':t.owner,'Rev':t.rev,'Status':status(t.status).label,'Submission Date':t.submittedDate,'Response Date':t.responseDate}));});if(includeReserved)reserved().forEach(d=>rows.push({'Form':'','Document Name':d.title,'Document Number':d.num,'Transmittal Number':'','Transmittal Title':'','Owner':'','Rev':'','Status':'','Submission Date':'','Response Date':''}));return rows;}
function exportCSV(){let rows=flatRows(view==='register'?filtered():data.transmittals,view!=='register'),heads=['Form','Document Name','Document Number','Transmittal Number','Transmittal Title','Owner','Rev','Status','Submission Date','Response Date'];const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';download(new Blob(['\ufeff'+[heads,...rows.map(r=>heads.map(h=>r[h]))].map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'CMA-DHC1295-register.csv');toast('CSV exported with one row per document–transmittal link.');}
function exportExcel(){if(!window.XLSX)throw Error('Excel export library is unavailable. Use CSV export instead.');let wb=XLSX.utils.book_new(),rows=flatRows(view==='register'?filtered():data.transmittals,view!=='register'),ws=XLSX.utils.json_to_sheet(rows);ws['!cols']=[8,65,38,34,55,26,8,36,18,18].map(w=>({wch:w}));XLSX.utils.book_append_sheet(wb,ws,'CMA Register');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{Project:'DHC1295',Notes:'Flat register; shared documents appear once per TN. Reserved documents have no TN. Missing records remain blank. Source JSON backup preserves full history.'}]),'Notes');XLSX.writeFile(wb,'CMA-DHC1295-register.xlsx');}
function dataDialog(){modal('<h2>Data & exports</h2><p>Export the current register or refresh the published project snapshot.</p><div class="actions" style="justify-content:flex-start">'+button('Export CSV','csv')+button('Export Excel','excel')+button('Refresh snapshot','refresh')+button('Reserved numbers ('+reserved().length+')','reserved')+'</div>'+(unlocked?'<div class="notice">Local editing affects this device only. Download the JSON snapshot to retain all history. Refresh replaces local data only after confirmation.</div><div class="actions" style="justify-content:flex-start">'+button('Download JSON backup','json')+button('Import JSON / Excel / CSV','import')+'</div>':'')+'<div class="subline" style="margin-top:18px">'+esc(data.transmittals.length+' transmittals · '+data.documents.length+' unique documents')+'</div>');}
function parseDoc(num){let m=num.match(/^CMA-1042-([A-Z0-9]{2,8})-([A-Z0-9]{2,8})-AZR-S03-(\d+)$/);if(!m)throw Error('Invalid CMA document number: '+num);return {type:m[1],discipline:m[2],serial:Number(m[3])};}
function parseTN(num){for(let form of Object.keys(CMA.FORMS)){let prefix=CMA.tnNumber(form,1).replace(/001$/,'');if(num.startsWith(prefix)&&/^\d+$/.test(num.slice(prefix.length)))return {form,serial:Number(num.slice(prefix.length))};}throw Error('Invalid CMA transmittal number: '+num);}
function importedDate(v,label){if(v===undefined||v===null||v==='')return '';if(v instanceof Date){return v.toISOString().slice(0,10);}let s=String(v).trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error(label+' must be YYYY-MM-DD.');return s;}
function mergeRows(rows){let n=clone(data),count=0;for(let r of rows){let dn=String(r['Document Number']||'').trim().toUpperCase(),tn=String(r['Transmittal Number']||'').trim().toUpperCase();if(!dn&&!tn)continue;count++;let d;if(dn){d=n.documents.find(d=>d.num===dn);if(!d){let x=parseDoc(dn);d={id:uid(),num:dn,...x,title:String(r['Document Name']||'').trim()};n.documents.push(d);}else if(r['Document Name']&&d.title!==String(r['Document Name']).trim())throw Error('Title differs for existing document '+dn+'. Correct its title with an audit reason first.');}if(!tn)continue;let t=n.transmittals.find(t=>t.num===tn);if(!t){let x=parseTN(tn);if(r.Form&&String(r.Form).trim()!==x.form)throw Error('Form does not match '+tn);let raw=String(r.Status||'').trim(),s=Object.keys(CMA.STATUS).find(k=>k===raw||status(k).label.toLowerCase()===raw.toLowerCase());if(raw&&!s)throw Error('Unknown status '+raw+' for '+tn);t={id:uid(),num:tn,...x,title:String(r['Transmittal Title']||'').trim(),rev:String(r.Rev??'').trim()||'0',status:s||'UNRECORDED',owner:String(r.Owner||'').trim(),submittedDate:importedDate(r['Submission Date'],'Submission Date'),responseDate:importedDate(r['Response Date'],'Response Date'),documentIds:[],history:[]};n.transmittals.push(t);}else{for(let [h,k] of [['Rev','rev'],['Owner','owner'],['Submission Date','submittedDate'],['Response Date','responseDate']])if(r[h]!==undefined&&r[h]!==''&&String(r[h]).trim()!==t[k])throw Error('Existing '+tn+' has different '+h+'. Use its detail workflow to preserve audit history.');if(r.Status&&String(r.Status)!==t.status&&String(r.Status)!==status(t.status).label)throw Error('Existing status differs for '+tn+'. Update it in workflow details.');}if(d&&!t.documentIds.includes(d.id))t.documentIds.push(d.id);}
if(!count)throw Error('No document or transmittal numbers found.');CMA.validate(n);return n;}
async function readImport(file){requireEditor();if(!file)return;try{let candidate;if(/\.json$/i.test(file.name)){candidate=JSON.parse(await file.text());CMA.validate(candidate);}else{if(!window.XLSX)throw Error('Excel import library is unavailable.');let wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});let rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});let heads=Object.keys(rows[0]||{});if(!heads.includes('Document Number')||!heads.includes('Transmittal Number'))throw Error('Expected flat headings: Form, Document Name, Document Number, Transmittal Number. Optional: Owner, Rev, Status, Submission Date, Response Date.');candidate=mergeRows(rows);}importCandidate=candidate;modal('<h2>Review import</h2><p>'+esc(file.name)+'</p><div class="detail-meta"><div><small>Project</small>DHC1295</div><div><small>Transmittals</small>'+candidate.transmittals.length+'</div><div><small>Unique documents</small>'+candidate.documents.length+'</div><div><small>History events</small>'+candidate.transmittals.reduce((s,t)=>s+t.history.length,0)+'</div></div><div class="notice">'+(/\.json$/i.test(file.name)?'JSON import replaces the local snapshot.':'Flat-file import merges links and new identities into existing data. Existing histories and shared documents are retained. Missing dates and statuses are not inferred.')+' Nothing is saved until you confirm.</div><div class="actions">'+button('Cancel','cancel-import')+button('Confirm & import','confirm-import','')+'</div>');}catch(e){importCandidate=null;error(e);}}
function pdfHeader(pdf,title,caption){pdf.setFillColor(241,244,248);pdf.rect(0,0,420,297,'F');pdf.setTextColor(20,33,61);pdf.setFont('helvetica','bold');pdf.setFontSize(20);pdf.text('CMA Security System Stage 3 | DHC1295',14,22,{maxWidth:265});pdf.setFont('helvetica','normal');pdf.setFontSize(11);pdf.text(title,14,32);pdf.setFontSize(8);pdf.setTextColor(90,105,125);pdf.text(pdf.splitTextToSize(caption,265).slice(0,2),14,39);let labels=['CLIENT','CONSULTANT','CONTRACTOR'];document.querySelectorAll('#print-parties img').forEach((img,i)=>{let x=290+i*39;pdf.setFontSize(6);pdf.text(labels[i],x+15,12,{align:'center'});if(img.complete&&img.naturalWidth){try{let w=Math.min(31,13*img.naturalWidth/img.naturalHeight),h=w*img.naturalHeight/img.naturalWidth;pdf.addImage(img.src,'PNG',x+(31-w)/2,16,w,h);}catch(e){pdf.text(img.alt,x,23);}}else pdf.text(img.alt,x,23);});}
function pdfTable(pdf,head,body,startY=50){pdf.autoTable({startY,head:[head],body,theme:'grid',margin:{left:14,right:14},styles:{fontSize:8,cellPadding:3,lineColor:[220,226,234],lineWidth:.15,fillColor:[255,255,255],textColor:[24,36,58],overflow:'linebreak'},headStyles:{fillColor:[224,231,241],textColor:[54,70,94],fontStyle:'bold'},alternateRowStyles:{fillColor:[255,255,255]},didDrawPage:()=>{pdf.setFontSize(7);pdf.setTextColor(100,112,130);pdf.text('OZA DC Hub | '+today()+' | Working days | '+pdf.internal.getNumberOfPages(),14,290);}});}
function exportPDF(){if(!window.jspdf?.jsPDF)throw Error('PDF library is unavailable. Please try again when connected.');let pdf=new jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a3'});if(typeof pdf.autoTable!=='function')throw Error('PDF table library is unavailable.');if(view==='register'){let caption='Filtered register · '+filtered().length+' of '+data.transmittals.length+' transmittals';let active=Object.entries(filters).filter(([,v])=>v).map(([k,v])=>k+': '+v).join(' | ');pdfHeader(pdf,'Transmittal register',caption+(active?' | '+active:''));pdfTable(pdf,['No','Transmittal number','Description','Owner','Rev','Status','With','Age'],filtered().map((t,i)=>[i+1,t.num,t.title,t.owner||'Not recorded',t.rev,status(t.status).label,withParty(t),age(t)===null?'—':age(t)+'d']));}else{pdfHeader(pdf,'Project dashboard','Current transmittal overview · '+today());let ks=kpis();ks.forEach((k,i)=>{let x=14+i*65;pdf.setFillColor(255,255,255);pdf.roundedRect(x,50,61,33,3,3,'F');pdf.setTextColor(24,36,58);pdf.setFontSize(24);pdf.text(String(k.n),x+5,65);pdf.setFontSize(8);pdf.text(k.name,x+5,75);});pdfTable(pdf,['Transmittal form','Count'],Object.entries(counts('form')),96);pdf.setFontSize(9);pdf.text(data.documents.length+' unique documents | '+reserved().length+' reserved numbers | '+data.transmittals.reduce((s,t)=>s+t.documentIds.length,0)+' TN-document links',14,90);pdf.addPage('a3','landscape');pdfHeader(pdf,'Project insights','Recorded data only · response timing is mean working days');pdfTable(pdf,['Dimension','Category','Transmittals / days'],[...Object.entries(counts('form')).map(([k,n])=>['Form',k,n]),...Object.entries(counts('discipline')).map(([k,n])=>['Discipline',k,n]),...Object.entries(counts('owner')).map(([k,n])=>['Owner',k,n]),...Object.entries(timing()).map(([k,n])=>['Mean response time',k,n.toFixed(1)+' days'])]);}pdf.save('CMA-DHC1295-'+view+'.pdf');toast('PDF downloaded.');}

function addCatalog(kind){requireEditor();let code=prompt(kind==='documentTypes'?'New document type code':'New discipline code');if(code===null)return;code=code.trim().toUpperCase();if(!/^[A-Z0-9]{2,8}$/.test(code))throw Error('Use 2–8 uppercase letters or digits.');if(kind==='documentTypes'&&code==='MAT')throw Error('Use MTS for Material Submittal, not MAT.');if(data.catalogs[kind][code])throw Error('This code already exists in this project.');let label=prompt('Name for '+code);if(label===null)return;label=label.trim();if(!label)throw Error('A name is required.');mutate(n=>{n.catalogs[kind][code]=label;});composeDoc();let fieldId=kind==='documentTypes'?'nd-type':'nd-disc';$(fieldId).value=code;$(fieldId).dispatchEvent(new Event('change'));toast('Added to this project.');}
async function action(name,el){switch(name){case'catalog-type':addCatalog('documentTypes');break;case'catalog-discipline':addCatalog('disciplines');break;case'register':nav('register');break;case'reset':openFilter({});break;case'data':dataDialog();break;case'refresh':await refresh();break;case'reserved':reservedDialog();break;case'workflow':workflow(el.dataset.id);break;case'correct-tn':correctTN(el.dataset.id);break;case'correct-doc':correctDoc(el.dataset.id);break;case'revision':{requireEditor();let t=data.transmittals.find(t=>t.id===el.dataset.id);if(confirm('Begin revision '+CMA.nextRevision(t)+' for '+t.num+'? Previous revision dates and owner will remain in history.')){mutate(n=>{let x=n.transmittals.find(t=>t.id===el.dataset.id);x.history.push(snapshot(x,'revision_snapshot'));CMA.startRevision(n,x.id,today());});detail(t.id);}break;}case'resume-draft':composer();break;case'pick-existing':pickExisting();break;case'compose-doc':composeDoc();break;case'add-doc':addDoc();break;case'remove-draft':saveDraftFields();draft.documents.splice(Number(el.dataset.index),1);composer();break;case'discard-draft':if(confirm('Discard this transmittal draft?')){draft=null;$('modal').close();}break;case'create-tn':await createTN();break;case'csv':exportCSV();break;case'excel':exportExcel();break;case'json':requireEditor();download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'cma-data.json');toast('JSON backup downloaded.');break;case'import':requireEditor();$('import-file').value='';$('import-file').click();break;case'cancel-import':importCandidate=null;dataDialog();break;case'confirm-import':requireEditor();if(!importCandidate)throw Error('No valid import preview.');commit(importCandidate);importCandidate=null;dataDialog();toast('Import saved locally.');break;}}
document.addEventListener('click',async e=>{let el=e.target.closest('button');if(!el)return;try{if(el.dataset.view){nav(el.dataset.view);return;}if(el.hasAttribute('data-kpi')){openFilter(kpis()[Number(el.dataset.kpi)].f);return;}if(el.dataset.filterKey){let key=el.dataset.filterKey,value=el.dataset.filterValue;if(key==='age')openFilter({group:'age:'+value});else openFilter({[key]:key==='owner'&&value==='Not recorded'?'__none':value});return;}if(el.dataset.tn){if($('n-form'))saveDraftFields();detail(el.dataset.tn);return;}if(el.dataset.doc){if($('n-form'))saveDraftFields();documentDetail(el.dataset.doc);return;}if(el.dataset.pick){let d=data.documents.find(d=>d.id===el.dataset.pick);if(!draft.documents.some(x=>x.id===d.id))draft.documents.push(clone(d));composer();return;}if(el.dataset.action)await action(el.dataset.action,el);}catch(x){error(x);}});
document.addEventListener('change',e=>{if(e.target.id?.startsWith('f-')){filters[e.target.id.slice(2)]=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='f-search'){filters.search=e.target.value;let start=e.target.selectionStart;render();$('f-search').focus();$('f-search').setSelectionRange(start,start);}});
$('modal-close').onclick=()=>{if($('n-form'))saveDraftFields();$('modal').close();};$('modal').addEventListener('cancel',()=>{if($('n-form'))saveDraftFields();});$('project').onchange=()=>{if($('project').value==='mpt09')location.href='./index.html';};$('refresh').onclick=refresh;$('lock').onclick=()=>unlock().catch(error);$('data-button').onclick=dataDialog;$('pdf').onclick=()=>{try{exportPDF();}catch(e){error(e);}};$('new-tn').onclick=()=>{try{newTN();}catch(e){error(e);}};$('import-file').onchange=()=>readImport($('import-file').files[0]);
function applyTheme(theme){document.documentElement.dataset.theme=theme;$('theme').innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(theme==='light'?'<path d="M20.8 13A9 9 0 0 1 11 3.2 9 9 0 1 0 20.8 13Z"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>')+'</svg><span>'+(theme==='light'?'Dark theme':'Light theme')+'</span>';$('theme').title=theme==='light'?'Switch to dark theme':'Switch to light theme';$('theme').setAttribute('aria-label',$('theme').title);}
try{applyTheme(localStorage.getItem(THEME)||'light');}catch(e){applyTheme('light');}$('theme').onclick=()=>{let t=document.documentElement.dataset.theme==='light'?'dark':'light';applyTheme(t);try{localStorage.setItem(THEME,t);}catch(e){}};
window.addEventListener('focus',poll);window.addEventListener('beforeunload',e=>{if(draft){e.preventDefault();e.returnValue='';}});
async function init(){try{if(!window.CMA)throw Error('Project engine did not load. Reload this page.');try{meta=JSON.parse(localStorage.getItem(META)||'{}');let stored=localStorage.getItem(KEY);if(stored){data=JSON.parse(stored);CMA.validate(data);}}catch(e){data=null;meta={};toast('Saved local data could not be loaded. The published snapshot will be used.');}if(!data){let r=await fetchSnapshot();data=r.snapshot;meta={baseFingerprint:r.fp,dirty:false};localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(META,JSON.stringify(meta));}render();await poll();setInterval(poll,60000);}catch(e){$('content').innerHTML='<div class="panel"><h2>Project data unavailable</h2><p>'+esc(e.message)+'</p><button class="button" onclick="location.reload()">Try again</button></div>';$('snapshot-state').textContent='Snapshot could not be loaded.';}}
window.CMA_UI={getData:()=>clone(data),getFilters:()=>({...filters}),getView:()=>view,refresh,poll,flatRows,mergeRows};init();
})();
